echo "C300: c_a11y1"
S=/workspace/nox/web/site; N=/workspace/nox
echo  | base64 -d > $S/nox-u-a11y.js
[ -f $S/chat.html.bak_c_a11y ] || cp -p $S/chat.html $S/chat.html.bak_c_a11y
grep -q nox-u-a11y.js $S/chat.html || sed -i 's#</body>#<script src="./nox-u-a11y.js?v=u1" defer></script>\n</body>#' $S/chat.html
grep -c "nox-u-a11y" $S/chat.html; curl -s -m5 -o /dev/null -w "a11y.js http=%{http_code}\n" localhost:8091/web/nox-u-a11y.js
echo "== live: sl-icon-button без label"
cat > /tmp/a11y_t.py <<'PY'
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(viewport={"width":1440,"height":900}); pg.goto("http://127.0.0.1:8091/web/chat.html"); pg.wait_for_timeout(7000)
    print(pg.evaluate("()=>{const a=[...document.querySelectorAll('sl-icon-button')];const bad=a.filter(x=>!(x.getAttribute('label')||x.label||x.getAttribute('aria-label')));return {total:a.length,nolabel:bad.length,sample:bad.slice(0,4).map(x=>x.outerHTML.slice(0,120))}}"))
    b.close()
PY
$N/venv/bin/python /tmp/a11y_t.py 2>&1 | tail -3
echo "== audit.json chat"
python3 - <<'PY'
import json
try:
    d=json.load(open("/workspace/nox/web/site/qa/audit.json")); c=d.get("chat") or {}
    print("ts",c.get("ts")); print(json.dumps([ (f.get("item","")[:60], f.get("detail")) for f in c.get("fails",[])],ensure_ascii=False)[:1800]); print(str(c.get("vision_raw"))[:500])
except Exception as e: print("audit.json error",e)
PY
ls -la --time-style=full-iso $S/qa/audit.json* | cut -c20-120
